vv->set_bounds(0, top, 960, 540);
root.add_child(vv);

if (vv->open_source("C:/path/video.mp4")) {   // 宽字符/中文路径安全
    vv->play();
    vv->set_loop(false);
    vv->set_speed(1.f);                        // 0.5x..2x
    vv->set_volume(0.8f);                      // 0..1
}

scene.subscribe(ui::ScenePhase::Frame, [&] {
    if (vv->advance(1.f / 60.f)) { /* 有帧，纹理已更新 */ }
});
